 66 | function hashSeed(s: string): number {
 67 |   let h = 2166136261;
 68 |   for (let i = 0; i < s.length; i++) {
 69 |     h ^= s.charCodeAt(i);
 70 |     h = Math.imul(h, 16777619);
 71 |   }
 72 |   return h >>> 0;
 73 | }
 74 | 
 75 | function mulberry32(seed: number): () => number {
 76 |   let a = seed;
 77 |   return function () {
 78 |     a |= 0;
 79 |     a = (a + 0x6d2b79f5) | 0;
 80 |     let t = Math.imul(a ^ (a >>> 15), 1 | a);
 81 |     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
 82 |     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
 83 |   };
 84 | }
 85 | 
 86 | function effectivePower(modelId: string, category: BenchmarkCategory): number {
 87 |   const base = BASE_POWER[modelId] ?? 0.75;
 88 |   const catShift = CAT_BASE[category] * (1.3 - base);
 89 |   const override = OVERRIDES[modelId]?.[category] ?? 0;
 90 |   return base + catShift + override;
 91 | }
 92 | 
 93 | function noteFor(modelId: string, benchmarkId: string): string | undefined {
 94 |   if (benchmarkId === "math500" || benchmarkId === "aime2024" || benchmarkId === "gsm8k") {
 95 |     if ((OVERRIDES[modelId]?.math ?? 0) > 0) return "CoT";
 96 |     return undefined;
 97 |   }
 98 |   if (benchmarkId === "mmmu") return "vision eval";
 99 |   if (benchmarkId === "swebench") return "agentic";
100 |   if (benchmarkId === "bbh" || benchmarkId === "arc-agi") return "CoT";
101 |   return undefined;
102 | }
103 | 
104 | function generateScores(): Score[] {
105 |   const out: Score[] = [];
106 |   for (const model of models) {
107 |     const missing = new Set(WEAK_MISSING[model.id] ?? []);
108 |     for (const bench of benchmarks) {
109 |       if (bench.category === "vision" && !model.modalities.includes("vision")) {
110 |         continue;
111 |       }
112 |       if (missing.has(bench.id)) continue;
113 | 
114 |       const power = effectivePower(model.id, bench.category);
115 |       const clamped = Math.max(0, Math.min(1, power));
116 |       const rng = mulberry32(hashSeed(model.id + ":" + bench.id));
117 |       const noiseAmp = bench.scaleMax * 0.04;
118 |       const noise = (rng() * 2 - 1) * noiseAmp;
119 |       let value = clamped * bench.scaleMax + noise;
120 |       value = Math.max(0, Math.min(bench.scaleMax, value));
121 |       value = Math.round(value * 10) / 10;
122 | 
123 |       out.push({
124 |         modelId: model.id,
125 |         benchmarkId: bench.id,
126 |         value,
127 |         date: model.releaseDate,
128 |         note: noteFor(model.id, bench.id),
129 |       });
130 |     }
131 |   }
132 |   return out;
133 | }
134 | 
135 | export const scores: Score[] = generateScores();
