  1 | import type { Benchmark, BenchmarkCategory, Model } from "../types";
  2 | import { benchmarks } from "../data/benchmarks";
  3 | import { getValue } from "../data/scores";
  4 | import { CATEGORIES } from "../types";
  5 | 
  6 | export interface RankRow {
  7 |   model: Model;
  8 |   avgRank: number;
  9 |   firsts: number;
 10 |   coverage: number; // fraction of visible benchmarks with a value
 11 | }
 12 | 
 13 | // Rank a list of models for a single benchmark (best first; missing last).
 14 | export function rankForBenchmark(
 15 |   models: Model[],
 16 |   benchmark: Benchmark
 17 | ): { model: Model; value: number | null; rank: number | null }[] {
 18 |   const present = models
 19 |     .map((m) => ({ model: m, value: getValue(m.id, benchmark.id) }))
 20 |     .filter((r) => r.value != null) as { model: Model; value: number }[];
 21 | 
 22 |   present.sort((a, b) =>
 23 |     benchmark.higherIsBetter ? b.value - a.value : a.value - b.value
 24 |   );
 25 |   const rankById = new Map<string, number>();
 26 |   present.forEach((r, i) => rankById.set(r.model.id, i + 1));
 27 | 
 28 |   return models.map((m) => ({
 29 |     model: m,
 30 |     value: getValue(m.id, benchmark.id),
 31 |     rank: rankById.get(m.id) ?? null,
 32 |   }));
 33 | }
 34 | 
 35 | // Average rank across several benchmarks; missing scores are excluded from the
 36 | // average rather than penalized. Precomputes per-benchmark ranks in a single
 37 | // pass (O(models × benchmarks)) instead of re-ranking per model per benchmark.
 38 | export function computeRanking(models: Model[], visible: Benchmark[]): RankRow[] {
 39 |   const n = visible.length;
 40 | 
 41 |   // Precompute: Map<benchmarkId, Map<modelId, rank>>
 42 |   const rankCache = new Map<string, Map<string, number>>();
 43 |   for (const bench of visible) {
 44 |     const ranked = rankForBenchmark(models, bench);
 45 |     const benchRanks = new Map<string, number>();
 46 |     for (const r of ranked) {
 47 |       if (r.rank != null) benchRanks.set(r.model.id, r.rank);
 48 |     }
 49 |     rankCache.set(bench.id, benchRanks);
 50 |   }
 51 | 
 52 |   const rows: RankRow[] = models.map((model) => {
 53 |     let sum = 0;
 54 |     let count = 0;
 55 |     let firsts = 0;
 56 |     for (const bench of visible) {
 57 |       const rank = rankCache.get(bench.id)?.get(model.id);
 58 |       if (rank != null) {
 59 |         sum += rank;
 60 |         count += 1;
 61 |         if (rank === 1) firsts += 1;
 62 |       }
 63 |     }
 64 |     return {
 65 |       model,
 66 |       avgRank: count > 0 ? sum / count : n + 1,
 67 |       firsts,
 68 |       coverage: n > 0 ? count / n : 0,
 69 |     };
 70 |   });
 71 | 
 72 |   rows.sort((a, b) => a.avgRank - b.avgRank);
 73 |   return rows;
 74 | }
 75 | 
 76 | export interface RadarPoint {
 77 |   category: BenchmarkCategory;
 78 |   value: number | null; // 0..1, normalized by scaleMax
 79 | }
 80 | 
 81 | // Average normalized score per category for one model (one radar axis each).
 82 | export function radarAverages(modelId: string): RadarPoint[] {
 83 |   const byCat = new Map<BenchmarkCategory, number[]>();
 84 |   for (const bench of benchmarks) {
 85 |     const v = getValue(modelId, bench.id);
 86 |     if (v == null) continue;
 87 |     const norm = bench.scaleMax > 0 ? v / bench.scaleMax : 0;
 88 |     const arr = byCat.get(bench.category) ?? [];
 89 |     arr.push(norm);
 90 |     byCat.set(bench.category, arr);
 91 |   }
 92 |   return (Object.keys(CATEGORY_ORDER) as BenchmarkCategory[]).map((category) => {
 93 |     const arr = byCat.get(category);
 94 |     if (!arr || arr.length === 0) return { category, value: null };
 95 |     return { category, value: arr.reduce((s, x) => s + x, 0) / arr.length };
 96 |   });
 97 | }
 98 | 
 99 | const CATEGORY_ORDER: Record<BenchmarkCategory, number> = {
100 |   knowledge: 0,
101 |   reasoning: 1,
102 |   math: 2,
103 |   coding: 3,
104 |   agentic: 4,
105 |   instruction: 5,
106 |   chat: 6,
107 |   vision: 7,
108 | };
109 | 
110 | export function sortModels(
111 |   models: Model[],
112 |   sort: { benchmarkId: string | null; dir: "asc" | "desc" } | null,
113 |   visible: Benchmark[]
114 | ): Model[] {
115 |   const list = [...models];
116 |   if (!sort || !sort.benchmarkId) {
117 |     const ranking = computeRanking(models, visible);
118 |     const rankById = new Map(ranking.map((r, i) => [r.model.id, i]));
119 |     list.sort((a, b) => (rankById.get(a.id)! - rankById.get(b.id)!));
120 |     return list;
121 |   }
122 |   const bench = benchmarks.find((b) => b.id === sort.benchmarkId)!;
123 |   list.sort((a, b) => {
124 |     const av = getValue(a.id, bench.id);
125 |     const bv = getValue(b.id, bench.id);
126 |     if (av == null && bv == null) return 0;
127 |     if (av == null) return 1;
128 |     if (bv == null) return -1;
129 |     const cmp = av - bv;
130 |     return sort.dir === "asc" ? cmp : -cmp;
131 |   });
132 |   return list;
133 | }
134 | 
135 | export interface CategoryAvg {
136 |   modelId: string;
137 |   avg: number; // normalized 0..1 (value / scaleMax, averaged)
138 |   n: number; // number of benchmarks counted
139 | }
140 | 
141 | // Normalized (value / scaleMax) averaged per category over *visible* benchmarks.
142 | export function categoryAverages(
143 |   models: Model[],
144 |   visible: Benchmark[]
145 | ): Record<BenchmarkCategory, CategoryAvg[]> {
146 |   const result = {} as Record<BenchmarkCategory, CategoryAvg[]>;
147 |   for (const cat of CATEGORIES) result[cat] = [];
148 | 
149 |   for (const cat of CATEGORIES) {
