 3 | // Interpolate between two rgb triplets, t in [0,1], with a fixed alpha.
 4 | function lerpRgba(
 5 |   a: [number, number, number],
 6 |   b: [number, number, number],
 7 |   t: number,
 8 |   alpha: number
 9 | ): string {
10 |   const r = Math.round(a[0] + (b[0] - a[0]) * t);
11 |   const g = Math.round(a[1] + (b[1] - a[1]) * t);
12 |   const bl = Math.round(a[2] + (b[2] - a[2]) * t);
13 |   return `rgba(${r}, ${g}, ${bl}, ${alpha})`;
14 | }
15 | 
16 | // Glass-friendly stops: cool blue (low) → green (high).
17 | const LOW_RGB: [number, number, number] = [59, 130, 246];
18 | const HIGH_RGB: [number, number, number] = [34, 197, 94];
