20 | export interface ColumnStats {
21 |   min: number;
22 |   max: number;
23 |   best: number;
24 |   worst: number;
25 |   avg: number;
26 |   count: number;
27 | }
28 | 
29 | // Returns normalized stats for a benchmark column using only present values.
30 | export function columnStats(
31 |   values: (number | null)[],
32 |   benchmark: Benchmark
33 | ): ColumnStats {
34 |   const present = values.filter((v): v is number => v != null);
35 |   if (present.length === 0) {
36 |     return { min: 0, max: 0, best: 0, worst: 0, avg: 0, count: 0 };
37 |   }
38 |   const sorted = [...present].sort((a, b) => a - b);
39 |   const best = benchmark.higherIsBetter ? sorted[sorted.length - 1] : sorted[0];
40 |   const worst = benchmark.higherIsBetter ? sorted[0] : sorted[sorted.length - 1];
41 |   const sum = present.reduce((s, v) => s + v, 0);
42 |   return {
43 |     min: Math.min(...present),
44 |     max: Math.max(...present),
45 |     best,
46 |     worst,
47 |     avg: sum / present.length,
48 |     count: present.length,
49 |   };
50 | }
51 | 
52 | // Maps a value to a translucent heatmap color relative to the column min/max.
53 | // Stops are glass-friendly: low scores read as a cool blue, high as green, and
54 | // the fill stays semi-transparent so the liquid-glass surface reads through.
55 | export function heatmapColor(
56 |   value: number | null,
57 |   stats: ColumnStats,
58 |   benchmark: Benchmark
59 | ): string {
60 |   if (value == null || stats.max === stats.min) {
61 |     return "transparent";
62 |   }
63 |   const span = (value - stats.min) / (stats.max - stats.min);
64 |   const t = benchmark.higherIsBetter ? span : 1 - span;
65 |   // Alpha scales from faint (low) to fairly saturated (high) for legibility.
66 |   const alpha = 0.24 + t * 0.58;
67 |   return lerpRgba(LOW_RGB, HIGH_RGB, t, alpha);
68 | }

