import { afterEach, describe, expect, it } from "vitest";
import { loadOfficialData } from "./official";
import { setActiveData, getValue, getScoreEntry } from "./registry";
import { models as demoModels } from "./models";
import { benchmarks as demoBenchmarks } from "./benchmarks";
import { scores as demoScores } from "./scores";

// Registry holds module-level state; reset to the demo dataset after every test
// so mutations never leak across tests.
function resetDemo() {
  setActiveData({
    models: demoModels,
    benchmarks: demoBenchmarks,
    scores: demoScores,
  });
}

describe("loadOfficialData", () => {
  it("maps the ledger export to app types with provenance preserved", () => {
    const off = loadOfficialData();
    expect(off.models.length).toBe(1);
    expect(off.benchmarks.length).toBe(1);
    expect(off.scores.length).toBe(1);

    // Unknown ledger category ("meta_registry") is bucketed as "other".
    expect(off.benchmarks[0].category).toBe("other");
    // Null family is filled with a neutral default.
    expect(off.models[0].family).toBe("unknown");

    const s = off.scores[0];
    expect(s.value).toBe(42.5);
    // Raw source value preserved exactly (not recalculated).
    expect(s.scoreRaw).toBe("42.50");
    expect(s.officialSourceId).toBe("fake_local_fixture");
    expect(s.captureStatus).toBe("parser_verified");
    expect(s.claimId).toBeTruthy();
  });
});

describe("registry dual-mode switching", () => {
  afterEach(resetDemo);

  it("getValue reads the active dataset and is the sole score path", () => {
    // Official mode: source-backed claim value.
    const off = loadOfficialData();
    setActiveData({
      models: off.models,
      benchmarks: off.benchmarks,
      scores: off.scores,
    });
    expect(getValue("fake_model_1", "hf_official_benchmarks")).toBe(42.5);
    const entry = getScoreEntry("fake_model_1", "hf_official_benchmarks");
    expect(entry?.officialSourceId).toBe("fake_local_fixture");

    // Missing cells render as no-data (null), not zero.
    expect(getValue("fake_model_1", "does-not-exist")).toBeNull();
    expect(getScoreEntry("fake_model_1", "does-not-exist")).toBeNull();

    // Switching back to demo: getValue reflects demo data and carries no
    // provenance (demo scores must not look like official claims).
    resetDemo();
    const demoVal = getValue("gpt-4o", "mmlu");
    expect(typeof demoVal).toBe("number");
    expect(demoVal).not.toBeNull();
    const demoEntry = getScoreEntry("gpt-4o", "mmlu");
    expect(demoEntry?.officialSourceId).toBeUndefined();
    expect(demoEntry?.scoreRaw).toBeUndefined();
  });
});

